    59  void Packet::setRawPacket(RawPacket* rawPacket, bool freeRawPacket, ProtocolType parseUntil, OsiModelLayer parseUntilLayer)
    60  {
    61          destructPacketData();
    62
    63          m_FirstLayer = nullptr;
    64          m_LastLayer = nullptr;
    65          m_ProtocolTypes = UnknownProtocol;
    66          m_MaxPacketLen = rawPacket->getRawDataLen();
    67          m_FreeRawPacket = freeRawPacket;
    68          m_RawPacket = rawPacket;
    69          m_CanReallocateData = true;
    70          if (m_RawPacket == nullptr)
    71                  return;
    72
    73          LinkLayerType linkType = m_RawPacket->getLinkLayerType();
    74
    75          m_FirstLayer = createFirstLayer(linkType);
    76
    77          m_LastLayer = m_FirstLayer;
    78          Layer* curLayer = m_FirstLayer;
    79          while (curLayer != nullptr && (curLayer->getProtocol() & parseUntil) == 0 && curLayer->getOsiModelLayer() <= parseUntilLayer)
    80          {
    81                  m_ProtocolTypes |= curLayer->getProtocol();
    82                  curLayer->parseNextLayer();
    83                  curLayer->m_IsAllocatedInPacket = true;
    84                  curLayer = curLayer->getNextLayer();
    85                  if (curLayer != nullptr)
    86                          m_LastLayer = curLayer;
    87          }
    88
    89          if (curLayer != nullptr && (curLayer->getProtocol() & parseUntil) != 0)
    90          {
    91                  m_ProtocolTypes |= curLayer->getProtocol();
    92                  curLayer->m_IsAllocatedInPacket = true;
    93          }
    94
    95          if (curLayer != nullptr &&  curLayer->getOsiModelLayer() > parseUntilLayer)
    96          {
    97                  m_LastLayer = curLayer->getPrevLayer();
    98                  delete curLayer;
    99                  m_LastLayer->m_NextLayer = nullptr;
   100          }
   101
   102          if (m_LastLayer != nullptr && parseUntil == UnknownProtocol && parseUntilLayer == OsiModelLayerUnknown)
   103          {
   104                  // find if there is data left in the raw packet that doesn't belong to any layer. In that case it's probably a packet trailer.
   105                  // create a PacketTrailerLayer layer and add it at the end of the packet
   106                  int trailerLen = (int)((m_RawPacket->getRawData() + m_RawPacket->getRawDataLen()) - (m_LastLayer->getData() + m_LastLayer->getDataLen()));
   107                  if (trailerLen > 0)
   108                  {
   109                          PacketTrailerLayer* trailerLayer = new PacketTrailerLayer(
   110                                          (uint8_t*)(m_LastLayer->getData() + m_LastLayer->getDataLen()),
   111                                          trailerLen,
   112                                          m_LastLayer,
   113                                          this);
   114
   115                          trailerLayer->m_IsAllocatedInPacket = true;
   116                          m_LastLayer->setNextLayer(trailerLayer);
   117                          m_LastLayer = trailerLayer;
   118                          m_ProtocolTypes |= trailerLayer->getProtocol();
   119                  }
   120          }
