   147  void Packet::destructPacketData()
   148  {
   149          Layer* curLayer = m_FirstLayer;
   150          while (curLayer != nullptr)
   151          {
   152                  Layer* nextLayer = curLayer->getNextLayer();
   153                  if (curLayer->m_IsAllocatedInPacket)
   154                          delete curLayer;
   155                  curLayer = nextLayer;
   156          }
   157
   158          if (m_RawPacket != nullptr && m_FreeRawPacket)
   159          {
   160                  delete m_RawPacket;
   161          }
   162  }
