   193  void Packet::reallocateRawData(size_t newSize)
   194  {
   195          PCPP_LOG_DEBUG("Allocating packet to new size: " << newSize);
   196
   197          // allocate a new array with size newSize
   198          m_MaxPacketLen = newSize;
   199
   200          // set the new array to RawPacket
   201          if (!m_RawPacket->reallocateData(m_MaxPacketLen))
   202          {
   203                  PCPP_LOG_ERROR("Couldn't reallocate data of raw packet to " << m_MaxPacketLen << " bytes");
   204                  return;
   205          }
   206
   207          // set all data pointers in layers to the new array address
   208          const uint8_t* dataPtr = m_RawPacket->getRawData();
   209
   210          Layer* curLayer = m_FirstLayer;
   211          while (curLayer != nullptr)
   212          {
   213                  PCPP_LOG_DEBUG("Setting new data pointer to layer '" << typeid(curLayer).name() << "'");
   214                  curLayer->m_Data = (uint8_t*)dataPtr;
   215                  dataPtr += curLayer->getHeaderLen();
   216                  curLayer = curLayer->getNextLayer();
   217          }
   218  }
